def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Find the three-cell horizontal seed, with endpoints defining line colors.
    for r,row in enumerate(grid):
        for c in range(w-2):
            if row[c] and row[c+1] and row[c+2]:
                a,b,d=row[c:c+3]
                if a != b and d != b:
                    # extend first color outward from its endpoint's row/col marker
                    for rr in range(h):
                        if rr != r: out[rr][c+1]=b
                    for cc in range(w):
                        if cc != c+1: out[r][cc]=d if cc>c+2 else (a if cc<c else out[r][cc])
                    # Markers of endpoint colors determine horizontal/vertical line origins.
                    for rr in range(h):
                        for cc in range(w):
                            if (rr,cc)!=(r,c) and (rr,cc)!=(r,c+2) and grid[rr][cc] in (a,d):
                                color=grid[rr][cc]
                                if color==a:
                                    for x in range(cc,c): out[rr][x]=a
                                else:
                                    for x in range(c+3,w): out[rr][x]=d
                    return out
    return out
